installer-gui-script.script:
function arcen_installation_check() {
  // Set by the command-line installer. Measured on the lab Mac: Installer.app
  // does not set it, `installer -pkg` does, and this check sees the caller's
  // environment where the package scripts do not.
  var commandLine = system.env.COMMAND_LINE_INSTALL == "1";
  var allowed = system.env.ARCEN_ALLOW_COMMAND_LINE_INSTALL == "1";
  if (commandLine && !allowed) {
    my.result.type = "Fatal";
    my.result.title = "Install Arcen Pier on the Mac itself";
    my.result.message =
      "Arcen Pier must be installed with Installer.app on this Mac, not from Terminal. " +
      "It needs privacy permissions that macOS only lets someone at the Mac approve: " +
      "Screen & System Audio Recording and Accessibility for Arcen Agent Helper. " +
      "Open the package in Finder and follow the steps. " +
      "Administrators whose Macs get these permissions some other way, such as an MDM " +
      "privacy profile, can install from Terminal on purpose with: " +
      "sudo ARCEN_ALLOW_COMMAND_LINE_INSTALL=1 installer -pkg <package> -target /";
    return false;
  }
  if (commandLine) {
    system.log("Arcen Pier: command-line install allowed by ARCEN_ALLOW_COMMAND_LINE_INSTALL");
  }
  return true;
}
